for(const row of data.original_shortages){const card=el('article',undefined,'product-choice');card.append(el('h3',`${row.name} · ${row.S}개 부족`));const candidates=data.review.candidates.filter(c=>c.source_component_id===row.component_id);if(!candidates.length)card.append(el('p',data.review.diagnostics.length?'일부 자료를 확인하지 못했습니다. 대체 후보가 없다고 확정할 수 없습니다.':'검토한 자료 범위에서 대체 근거를 찾지 못했습니다. 원부품 구매 검토를 요청할 수 있습니다.'));for(const c of candidates){card.append(el('span','검토 후보 · 적용 미승인','tag pending'),el('p',`다른 설계 개정에 사용된 부품: ${c.name}`),el('p','개정 이력에는 교체 시 R50·R51을 실장하지 않았다고 기록되어 있습니다. 기존 주변 회로를 유지한 직접 대체로 적용할 수 없습니다.'),el('p','기술 검토: 핀맵·패키지·전기 조건 및 R50/R51 영향 확인 필요. R6의 충전 전류 변경은 같은 개정의 별도 기록입니다. 계약 검토: 고객의 개정 변경·대체 허용 확인 필요. 후보의 재고도 별도 확인해야 합니다.'));const evidence=el('details');evidence.append(el('summary','검토 근거 보기'));for(const source of data.source?.nodes||[])if(source.locator)evidence.append(el('p',source.locator),el('p',source.description));card.append(evidence);}view.append(card);}
view.append(el('h2','2. 부족한 부품에 대체 수량을 적용하세요'));const compare=el('button','특정 부품 대체 검토·수량 계산','primary');compare.onclick=()=>action(()=>showReplacements(id,itemIndex));view.append(compare);
if(data.draft&&!data.draft_current){const old=el('details');old.append(el('summary','이전에 저장한 구매 문서 보기'),el('p','이전 문서는 보존되어 있습니다. 적용안 선택 후 현재 부족분으로 새 초안을 작성하세요.'),el('pre',data.draft.markdown,'preview'));view.append(old);}
