const planButton=el('button','생산계획 확인·자재 예약 →','primary');planButton.onclick=()=>action(()=>showReservationPlan(id,itemIndex));view.append(planButton);
if(!data.shortages.length){view.append(el('p',`확인된 구매 부족분이 없습니다. 미확인 ${data.unknown_count}종은 별도 확인이 필요합니다.`));view.scrollIntoView({behavior:'smooth'});return;}
view.append(el('h2','3. 선택한 안의 구매 필요 부품을 확인하세요'),el('p','제조팀은 필요한 품목·수량·시점·기술 제약을 정리합니다. 구매팀이 공급사와 가격·납기·물류 조건을 비교하고 발주 수량을 결정합니다.'),el('p',`부족량 미확인 ${data.unknown_count}종은 이번 요청에 포함되지 않습니다. 재고 기준: ${data.stock_label}.`));
