const labels={contract_item_id:'계약 품목 번호',configuration_id:'제품 구성 식별',fulfilled_quantity:'기존 이행 수량',allocated_quantity:'기존 배정 수량',planned_input_quantity:'신규 생산 검토 수량',ordered_quantity:'주문 수량',delivery_due:'고객 납기',constraints:'변경·대체 조건'};
