const editor=el('details');editor.append(el('summary','계약 내용 수정 · 원문 근거 · 전체 확인 대상'));
const staleNotice=el('p','수정 중입니다. 아래 수정 내용을 저장하면 자동 검토를 다시 계산합니다.');staleNotice.hidden=true;view.append(staleNotice);
